import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=30);o=r.get_obs(depth=True,video='none');cam='egocentric_mirrored_camera';im=o.last[cam];d=o.last_depth[cam];K=np.array(o.meta['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);R=E[:,:3];t=E[:,3];inv=np.linalg.inv(R)
pts=[];uvs=[]
for v in range(20,155):
 for u in range(510,625):
  pix=im[v,u].astype(float); z=d[v,u]
  if pix.mean()<65 and z>0:
   xyz=inv@(np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z])-t)
   if .1<xyz[2]<.4 and .30<xyz[0]<.52 and .05<xyz[1]<.33:
    pts.append(xyz);uvs.append([u,v])
a=np.array(pts);uv=np.array(uvs);print('n',len(a),'world xyz percentiles',np.quantile(a,[.05,.25,.5,.75,.95],axis=0),'uv',uv.min(0),uv.max(0))
# 2-means on each horizontal axis, report centers and counts, nearest vertical region z=.14-.21
for zlo,zhi in [(.14,.21),(.14,.3)]:
 b=a[(a[:,2]>zlo)&(a[:,2]<zhi)];
 print('z',zlo,zhi,'n',len(b),'xybounds',b[:,:2].min(0),b[:,:2].max(0))
 for ax in [0,1]:
  vals=b[:,ax]; c1,c2=np.quantile(vals,[.25,.75]);
  for i in range(20):
   m=(abs(vals-c1)<abs(vals-c2)); n1=vals[m].mean() if m.any() else c1;n2=vals[~m].mean() if (~m).any() else c2
   if abs(n1-c1)+abs(n2-c2)<1e-6:break
   c1,c2=n1,n2
  print('axis',ax,'centers/count',c1,int(m.sum()),c2,int((~m).sum()))
print('pose',o.meta['proprio']['now'][8:15])
